(()=>{'use strict';const form=document.getElementById('wifiForm'),status=document.getElementById('wifiStatus'),summary=document.getElementById('wifiSummary'),key='rf-wifi-setup-v1',get=id=>form.elements.namedItem(id);let restoring=false;
function context(){const indoor=get('environment').value==='indoor';for(const [id,on]of [['indoorFields',indoor],['outdoorFields',!indoor]]){const node=document.getElementById(id);node.hidden=!on;for(const input of node.querySelectorAll('input'))input.disabled=!on}get('exponent').disabled=get('model').value==='fspl'}
function data(){return Object.fromEntries(new FormData(form))}
function render(){const d=data();summary.replaceChildren();const dl=document.createElement('dl');for(const [label,value]of [['โครงการ',d.project||'ยังไม่ระบุ'],['พื้นที่',d.environment==='indoor'?'Indoor · ชั้น '+d.floor:'Outdoor'],['ขนาดพื้นที่',d.width+' × '+d.length+' m'],['จุดกระจายสัญญาณ',d.apName+' · X '+d.apX+', Y '+d.apY+' m'],['วิทยุ',d.band+' GHz · '+d.frequency+' MHz · BW '+d.bandwidth+' MHz'],['กำลังส่ง / เกน / Loss',d.txPower+' dBm / '+d.apGain+' dBi / '+d.apLoss+' dB'],['เป้าหมายรับ',d.threshold+' dBm · SNR '+d.snr+' dB'],['แบบจำลอง',d.model==='fspl'?'Free-space':'Log-distance · n = '+d.exponent]]){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);dl.append(row)}summary.append(dl)}
function validate(){for(const id of ['apX','apY','frequency','bandwidth','standard'])get(id).setCustomValidity('');if(+get('apX').value>+get('width').value)get('apX').setCustomValidity('ตำแหน่ง X ต้องอยู่ภายในความกว้างพื้นที่');if(+get('apY').value>+get('length').value)get('apY').setCustomValidity('ตำแหน่ง Y ต้องอยู่ภายในความยาวพื้นที่');const band=get('band').value,f=+get('frequency').value,[low,high]=band==='2.4'?[2400,2500]:band==='5'?[4900,5925]:[5925,7125];if(f<low||f>high)get('frequency').setCustomValidity('ความถี่ไม่อยู่ในย่านที่เลือก');const bw=+get('bandwidth').value,st=get('standard').value;if((band==='2.4'&&bw>40)||(bw===320&&band!=='6'))get('bandwidth').setCustomValidity('Bandwidth ไม่สอดคล้องกับย่านความถี่');if((st==='802.11ac'&&band!=='5')||(st==='802.11a'&&band!=='5')||(st==='802.11g'&&band!=='2.4')||(st==='802.11n'&&band==='6'))get('standard').setCustomValidity('มาตรฐานไม่สอดคล้องกับย่านความถี่');if((['802.11a','802.11g'].includes(st)&&bw!==20)||(st==='802.11n'&&bw>40)||(bw===320&&st!=='802.11be'))get('bandwidth').setCustomValidity('Bandwidth ไม่สอดคล้องกับมาตรฐานที่เลือก')}
form.addEventListener('input',()=>{validate();render();if(!restoring)status.textContent='มีการแก้ไข · กดตรวจสอบและบันทึกเพื่อเก็บค่าล่าสุด'});form.addEventListener('change',e=>{if(e.target===get('band')){get('frequency').value={'2.4':2412,'5':5180,'6':5955}[get('band').value];get('channel').value='';get('bandwidth').value='20'}context();validate();render()});form.addEventListener('submit',e=>{e.preventDefault();validate();if(!form.reportValidity())return;try{const values=Object.fromEntries(Array.from(form.elements).filter(x=>x.name).map(x=>[x.name,x.value]));localStorage.setItem(key,JSON.stringify({schema:1,values}));status.textContent='ตรวจสอบและบันทึกพารามิเตอร์แล้ว · ยังไม่ได้คำนวณ Heatmap'}catch{status.textContent='ตรวจสอบแล้ว แต่เบราว์เซอร์ไม่อนุญาตให้บันทึกค่า'}render()});document.getElementById('wifiReset').onclick=()=>{form.reset();context();validate();render();try{localStorage.removeItem(key)}catch{}status.textContent='คืนค่าเริ่มต้นแล้ว · ค่าเริ่มต้นเป็นตัวอย่าง ยังไม่ได้คำนวณ'};
try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.schema===1&&saved.values){restoring=true;for(const [id,value]of Object.entries(saved.values)){const input=get(id);if(input&&typeof value==='string')input.value=value}status.textContent='เรียกคืนพารามิเตอร์ที่บันทึกในเครื่องแล้ว · ยังไม่ได้คำนวณ Heatmap'}}catch{status.textContent='อ่านค่าที่บันทึกไม่ได้ · ใช้ค่าเริ่มต้น'}finally{restoring=false}context();validate();render();
})();
